      "emptySaved": "영구 저장이 없습니다. 결과 화면에서 「리플레이 저장」하거나 「최근」에서 「영구 보관」하세요.",
      "preserve": "영구 보관",
      "preservedToast": "리플레이를 「영구 보관」으로 이동했습니다",
      "recentHint": "최근 10경기에서 자동 저장됩니다. 가장 오래된 항목부터 교체됩니다.",
      "recentSection": "최근 매치",
      "savedHint": "결과 화면에서 저장하거나, 「최근」 리플레이를 여기서 영구 보관합니다.",
      "savedSection": "영구 보관",
