  function deepFillI18n(target, src) {
    if (!src || typeof src !== 'object') return;
    Object.keys(src).forEach(function (k) {
      if (src[k] && typeof src[k] === 'object' && !Array.isArray(src[k])) {
        if (!target[k] || typeof target[k] !== 'object') target[k] = {};
        deepFillI18n(target[k], src[k]);
      } else if (target[k] == null) {
        target[k] = src[k];
      }
    });
  }
  function deepMergeOverwrite(target, src) {
    if (!src || typeof src !== 'object') return;
    Object.keys(src).forEach(function (k) {
      if (src[k] && typeof src[k] === 'object' && !Array.isArray(src[k])) {
        if (!target[k] || typeof target[k] !== 'object') target[k] = {};
        deepMergeOverwrite(target[k], src[k]);
      } else {
        target[k] = src[k];
      }
    });
  }
  LOCALES.forEach(function (loc) {
    if (!STRINGS[loc]) STRINGS[loc] = {};
    deepFillI18n(STRINGS[loc], I18N_FALLBACKS);
    if (loc !== 'en' && I18N_SOCIAL_LOCALES[loc]) {
      deepMergeOverwrite(STRINGS[loc], I18N_SOCIAL_LOCALES[loc]);
    }
  });

  mergeLocaleAliases(STRINGS.en);
  mergeLocaleAliases(STRINGS.ja);
  mergeLocaleAliases(STRINGS.es);
  mergeLocaleAliases(STRINGS.ko);
  if (STRINGS.zh) mergeLocaleAliases(STRINGS.zh);
  if (STRINGS.th) mergeLocaleAliases(STRINGS.th);
  if (STRINGS.pt) mergeLocaleAliases(STRINGS.pt);
  if (STRINGS.ja && STRINGS.ja.options) {
    STRINGS.ja.options.leaveActive = STRINGS.ja.options.leaveActive || '進行中の対戦を退出';
  }
  if (STRINGS.ja && STRINGS.ja.auth) {
    STRINGS.ja.auth.skipReconnect = STRINGS.ja.auth.skipReconnect || '対戦を退出して続ける';
  }

  function getLocale() {
    try {
      var stored = localStorage.getItem(LLTCG_LOCALE_KEY);
      if (stored && LOCALES.indexOf(stored) !== -1) return stored;
    } catch (e) { /* ignore */ }
    return 'en';
  }

  function setLocale(loc) {
    if (LOCALES.indexOf(loc) === -1) loc = 'en';
    try { localStorage.setItem(LLTCG_LOCALE_KEY, loc); } catch (e) { /* ignore */ }
    try {
      document.documentElement.lang = loc === 'zh' ? 'zh-Hans' : (loc === 'pt' ? 'pt-BR' : loc);
    } catch (e2) { /* ignore */ }
    try {
      if (document.body) {
        document.body.classList.remove('locale-ja', 'locale-ko', 'locale-zh', 'locale-th');
        if (loc === 'ja' || loc === 'ko' || loc === 'zh' || loc === 'th') document.body.classList.add('locale-' + loc);
      }
    } catch (e3) { /* ignore */ }
  }

  function lookupPath(obj, key) {
    if (!obj || !key) return undefined;
    var parts = String(key).split('.');
    var cur = obj;
    for (var i = 0; i < parts.length; i++) {
      if (cur == null || typeof cur !== 'object') return undefined;
      cur = cur[parts[i]];
    }
    return cur;
  }

  function interpolate(str, vars) {
    if (!vars || typeof str !== 'string') return str;
    return str.replace(/\{([^}]+)\}/g, function (_m, name) {
      return vars[name] != null ? String(vars[name]) : _m;
    });
  }

  function t(key, vars) {
    var loc = getLocale();
    var val = lookupPath(STRINGS[loc], key);
    if (val == null && (loc === 'ja' || loc === 'es' || loc === 'ko' || loc === 'zh' || loc === 'th' || loc === 'pt')) val = lookupPath(STRINGS.en, key);
    if (typeof val === 'string') return interpolate(val, vars);
    return key;
  }

  /** Like t(), but if the key is missing return fallback instead of the raw key path. */
  function tt(key, fallback, vars) {
    var val = t(key, vars);
    if (val == null || val === key) {
      return fallback != null ? interpolate(String(fallback), vars) : key;
    }
    return val;
  }

  function applyI18n(root) {
    var el = root || document;
    if (!el || !el.querySelectorAll) return;

    el.querySelectorAll('[data-i18n]').forEach(function (node) {
      if (node.id === 'auth-status') {
        var boot = node.getAttribute('data-auth-boot') || 'pending';
        if (boot === 'pending' || boot === 'booting') return;
      }
      var key = node.getAttribute('data-i18n');
      if (!key) return;
      var text = t(key);
      // Missing keys resolve to the key itself — keep HTML/source fallback so UI
      // never flashes raw paths like "sleeveShop.backHub".
      if (text === key) {
        var existing = (node.textContent || '').trim();
        if (existing && existing !== key) return;
      }
      if (node.getAttribute('data-i18n-html') === '1') node.innerHTML = text;
      else node.textContent = text;
    });

    el.querySelectorAll('[data-i18n-placeholder]').forEach(function (node) {
      var key = node.getAttribute('data-i18n-placeholder');
      if (!key) return;
      var text = t(key);
      if (text === key) {
        var existing = (node.getAttribute('placeholder') || '').trim();
        if (existing && existing !== key) return;
      }
      node.placeholder = text;
    });

    el.querySelectorAll('[data-i18n-title]').forEach(function (node) {
      var key = node.getAttribute('data-i18n-title');
      if (!key) return;
      var text = t(key);
      if (text === key) {
        var existing = (node.getAttribute('title') || '').trim();
        if (existing && existing !== key) return;
      }
      node.title = text;
    });

    el.querySelectorAll('[data-i18n-aria-label]').forEach(function (node) {
      var key = node.getAttribute('data-i18n-aria-label');
      if (!key) return;
      var text = t(key);
      if (text === key) {
        var existing = (node.getAttribute('aria-label') || '').trim();
        if (existing && existing !== key) return;
      }
      node.setAttribute('aria-label', text);
    });

    el.querySelectorAll('select option[data-i18n]').forEach(function (node) {
      var key = node.getAttribute('data-i18n');
      if (!key) return;
      var text = t(key);
      if (text === key) {
        var existing = (node.textContent || '').trim();
        if (existing && existing !== key) return;
      }
      node.textContent = text;
    });

    // Keep language picker closed-state flag + label aligned with active locale
    if (typeof LOCALE_PICKER_IDS !== 'undefined' && LOCALE_PICKER_IDS) {
      LOCALE_PICKER_IDS.forEach(function (id) {
        syncLocaleSelect(document.getElementById(id));
      });
    }
  }

